using System.Collections.Generic;

/// <summary>
/// All 70 NPC templates based on D&D 3.5e DMG Chapter 4 (p.110-127).
/// PHB Classes: 11 × 5 levels (1, 5, 10, 15, 20) = 55 templates
/// NPC Classes: 5 × 3 levels (1, 5, 10) = 15 templates
/// Stats derived from DMG NPC guidelines with elite/nonelite arrays.
/// </summary>
public static class TemplateData
{
    public static List<NPCTemplate> GetAllTemplates()
    {
        var templates = new List<NPCTemplate>();

        // PHB Classes — 11 classes × 5 levels
        AddFighterTemplates(templates);
        AddRogueTemplates(templates);
        AddClericTemplates(templates);
        AddWizardTemplates(templates);
        AddMonkTemplates(templates);
        AddBarbarianTemplates(templates);
        AddSorcererTemplates(templates);
        AddRangerTemplates(templates);
        AddPaladinTemplates(templates);
        AddBardTemplates(templates);
        AddDruidTemplates(templates);

        // NPC Classes — 5 classes × 3 levels
        AddAdeptTemplates(templates);
        AddAristocratTemplates(templates);
        AddCommonerTemplates(templates);
        AddExpertTemplates(templates);
        AddWarriorTemplates(templates);

        return templates;
    }

